import{_ as t,o,c as d,a2 as a}from"./chunks/framework.DYPTBNgj.js";const f=JSON.parse('{"title":"Server CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"operations/server-cli-reference.md","filePath":"operations/server-cli-reference.md"}'),r={name:"operations/server-cli-reference.md"};function c(s,e,n,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="server-cli-reference" tabindex="-1">Server CLI Reference <a class="header-anchor" href="#server-cli-reference" aria-label="Permalink to &quot;Server CLI Reference&quot;">​</a></h1><p>Every flag <code>aerini-server</code> accepts, for both the <code>serve</code> and <code>api</code> subcommands, plus the control subcommands (<code>list</code>, <code>stop</code>, <code>start</code>, <code>restart</code>, <code>status</code>, <code>tokens</code>) and <code>restore-key</code>. For what each mode is for and how to get one running, see <a href="./server-deploy">Server Deployment</a>. For the reasoning behind the security-relevant defaults, see <a href="./../guide/security">Security</a>.</p><p>The whole binary accepts <code>--version</code>; every subcommand accepts <code>--help</code> for this same information printed from the binary itself.</p><h2 id="serve" tabindex="-1"><code>serve</code> <a class="header-anchor" href="#serve" aria-label="Permalink to &quot;`serve`&quot;">​</a></h2><p>Runs one workflow exported from the desktop app (<strong>Export → Export for Server</strong>).</p><table tabindex="0"><thead><tr><th>Flag</th><th>Env var</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>--config &lt;path&gt;</code></td><td></td><td><code>aerini-server.json</code></td><td>Path to the config file produced by the export.</td></tr><tr><td><code>--port &lt;port&gt;</code></td><td></td><td>none</td><td>Overrides the status page port set in <code>aerini-server.json</code>. Leave unset to use that file&#39;s own port.</td></tr><tr><td><code>--bind &lt;address&gt;</code></td><td><code>AERINI_BIND</code></td><td><code>127.0.0.1</code></td><td>Interface the status page binds to. Set to <code>0.0.0.0</code> to expose it beyond localhost. An IPv6 address may be written with or without brackets (<code>::1</code> or <code>[::1]</code>).</td></tr><tr><td><code>--trusted-proxy-count &lt;n&gt;</code></td><td><code>AERINI_TRUSTED_PROXY_COUNT</code></td><td><code>0</code></td><td>Reverse-proxy hops to trust when reading <code>X-Forwarded-For</code>. Must match your proxy topology exactly, too high a value lets a client spoof its IP and dodge per-IP rate limiting.</td></tr><tr><td><code>--allow-shell</code></td><td></td><td><code>false</code></td><td>Enables Shell Command nodes. If the workflow has one and this is left unset, the server prints a startup warning instead of refusing to start.</td></tr><tr><td><code>--allow-code</code></td><td></td><td><code>false</code></td><td>Enables Code (JS) nodes. Same startup-warning behavior as <code>--allow-shell</code> if the workflow has one and this is unset.</td></tr><tr><td><code>--allow-database</code></td><td></td><td><code>false</code></td><td>Enables Database nodes (PostgreSQL, MySQL, SQLite, Redis). Same startup-warning behavior if the workflow has one and this is unset.</td></tr><tr><td><code>--allow-legacy-run-secret</code></td><td></td><td><code>false</code></td><td>Lets the server start when the config&#39;s <code>run_secret</code> is a legacy BLAKE3 hash, or a plain-text secret from an even older export, instead of argon2id. Without it, either makes the server refuse to start. With it, the server logs a warning saying which format it found. <code>serve</code>-only, since only <code>serve</code> has a <code>run_secret</code> at all.</td></tr><tr><td><code>--file-sandbox-dir &lt;dir&gt;</code></td><td></td><td>none</td><td>Restricts File and Save to Folder node reads and writes, and the paths a <code>.wasm</code> plugin may watch with <code>fs-watch</code>, to this directory tree. If the workflow has a File node and this is left unset, the server prints a startup warning and File nodes can reach any path the process can. <code>api</code> mode handles the unset case differently, see below.</td></tr><tr><td><code>--i-acknowledge-partial-sandbox</code></td><td></td><td><code>false</code></td><td><code>serve</code>-only. Required to start with <code>--allow-code --code-sandbox</code> on macOS or Windows, see <a href="#platform-behavior-of---code-sandbox">Platform behavior of <code>--code-sandbox</code></a> below.</td></tr><tr><td><code>--ssrf-firewall-acknowledged</code></td><td></td><td><code>false</code></td><td>Suppresses the startup warning about the <a href="./../glossary#ssrf">SSRF</a> remaining DNS-rebinding gap (Postgres and MySQL connections with <code>verify-full</code> or <code>VERIFY_IDENTITY</code>) when bound to a non-loopback address. Pass it only once a host-level egress firewall is actually in place.</td></tr><tr><td><code>--parallel-execution</code></td><td></td><td><code>false</code></td><td>Runs independent workflow branches concurrently instead of sequentially.</td></tr><tr><td><code>--max-concurrent-nodes &lt;n&gt;</code></td><td></td><td><code>8</code></td><td>Caps simultaneous nodes when <code>--parallel-execution</code> is set; ignored otherwise. A value below <code>1</code> is clamped to <code>1</code>, not rejected.</td></tr><tr><td><code>--max-workflow-duration-secs &lt;secs&gt;</code></td><td></td><td>none (no limit)</td><td>Server-level ceiling on one workflow execution, applied as <code>min(the workflow&#39;s own duration setting, this value)</code> when the workflow has one. A value outside 10 to 86400 (24 hours) is clamped to that range rather than rejected.</td></tr><tr><td><code>--code-sandbox</code></td><td></td><td><code>false</code></td><td>Applies module import and permission restrictions to Code (JS) nodes, plus CPU/memory limits on Linux. See <a href="#platform-behavior-of---code-sandbox">Platform behavior of <code>--code-sandbox</code></a> below.</td></tr><tr><td><code>--max-code-memory-mb &lt;mb&gt;</code></td><td></td><td><code>512</code> (Linux only)</td><td>Memory a sandboxed Code node&#39;s script may use. Aerini adds 2 GB of address space for Node.js&#39;s own startup on top (4 GB on Linux arm64, where the startup reservation has not been measured), so the process limit is this value plus that amount. Only takes effect with <code>--allow-code --code-sandbox</code> on Linux; no effect on macOS or Windows.</td></tr><tr><td><code>--plugin-dir &lt;dir&gt;</code></td><td></td><td>none</td><td>Directory of <code>.wasm</code> plugin nodes to load. A file that fails to load is skipped with a warning. <code>serve</code> reloads this directory on <code>SIGHUP</code> without restarting the process.</td></tr></tbody></table><h2 id="api" tabindex="-1"><code>api</code> <a class="header-anchor" href="#api" aria-label="Permalink to &quot;`api`&quot;">​</a></h2><p>Runs the multi-workflow REST API, with bearer-token auth and no export package or config file, everything here is a flag or an environment variable.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Env var</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>--token &lt;token&gt;</code></td><td><code>AERINI_TOKEN</code></td><td>auto-generated</td><td>Bearer token for API auth. If you set one, it must be at least 32 characters, the server exits with an error otherwise. Left unset on a first run (no tokens exist yet), the server generates a 43-character token, prints it once to stderr, and grants it all three <a href="./../glossary#scoped-token">scopes</a> (<code>read</code>, <code>write</code>, <code>admin</code>). On later restarts it keeps the tokens already stored and prints nothing, so save the first one. A <code>--token</code> the server doesn&#39;t already know is added as a new admin token and the server warns that the older tokens stay active; revoke them with <code>tokens revoke</code>. A <code>--token</code> that was revoked stops the server with an error. The server also refuses to start when no unrevoked, unexpired admin token exists: start it once with <code>--token &lt;new token&gt;</code> to add one.</td></tr><tr><td><code>--port &lt;port&gt;</code></td><td><code>AERINI_PORT</code></td><td><code>7700</code></td><td>Port to listen on. Unlike <code>serve</code>&#39;s <code>--port</code>, this one is env-backed and always has a default.</td></tr><tr><td><code>--data-dir &lt;dir&gt;</code></td><td><code>AERINI_DATA_DIR</code></td><td><code>~/.aerini-server</code></td><td>Directory for the SQLite database and the token/credential key file. <code>~</code> or a leading <code>~/</code> expands to your home directory (<code>$HOME</code>, or <code>USERPROFILE</code> on Windows when <code>HOME</code> is unset); <code>~name/...</code> is used as written. The server exits with an error if it needs a home directory and can&#39;t find one. A folder the server creates is owner-only (<code>0700</code> on Unix); an existing folder keeps its permissions, and the server logs a warning at start-up when group or other users can access it.</td></tr><tr><td><code>--allow-origin &lt;list&gt;</code></td><td></td><td>none</td><td>Comma-separated additional origins allowed to call the API. Localhost origins (<code>http://localhost[:port]</code>, <code>http://127.0.0.1[:port]</code>, <code>http://[::1][:port]</code>) are always allowed regardless of this flag.</td></tr><tr><td><code>--allow-env-vars &lt;list&gt;</code></td><td></td><td>none</td><td>Comma-separated environment variable names a workflow may read via <code>{{$env.VAR}}</code>. Anything not listed resolves to an empty string.</td></tr><tr><td><code>--bind &lt;address&gt;</code></td><td><code>AERINI_BIND</code></td><td><code>127.0.0.1</code></td><td>Same as <code>serve</code>&#39;s <code>--bind</code>, including IPv6 addresses with or without brackets.</td></tr><tr><td><code>--file-sandbox-dir &lt;dir&gt;</code></td><td></td><td><code>&lt;data-dir&gt;/files</code></td><td>Restricts File and Save to Folder node I/O, and the paths a <code>.wasm</code> plugin may watch with <code>fs-watch</code>, to this directory. Unlike <code>serve</code>, leaving this unset doesn&#39;t just warn: the server creates <code>&lt;data-dir&gt;/files</code> and uses it as the sandbox automatically.</td></tr><tr><td><code>--trusted-proxy-count &lt;n&gt;</code></td><td><code>AERINI_TRUSTED_PROXY_COUNT</code></td><td><code>0</code></td><td>Same as <code>serve</code>&#39;s.</td></tr><tr><td><code>--allow-shell</code></td><td></td><td><code>false</code></td><td>Enables Shell Command nodes. Unlike <code>serve</code>, this prints its startup warning banner whenever the flag itself is passed, regardless of whether any current workflow has a Shell Command node yet, since any token with <code>write</code> scope can create one later.</td></tr><tr><td><code>--allow-code</code></td><td></td><td><code>false</code></td><td>Enables Code (JS) nodes. Same always-on-when-passed warning pattern as <code>--allow-shell</code>.</td></tr><tr><td><code>--allow-database</code></td><td></td><td><code>false</code></td><td>Enables Database nodes. Same always-on-when-passed warning pattern.</td></tr><tr><td><code>--code-sandbox</code></td><td></td><td><code>false</code></td><td>Same as <code>serve</code>&#39;s. See <a href="#platform-behavior-of---code-sandbox">Platform behavior of <code>--code-sandbox</code></a> below.</td></tr><tr><td><code>--ssrf-firewall-acknowledged</code></td><td></td><td><code>false</code></td><td>Same as <code>serve</code>&#39;s.</td></tr><tr><td><code>--keychain</code></td><td></td><td><code>false</code></td><td>Backs the credential/token encryption key with the OS keychain (macOS Keychain, Windows Credential Manager, Linux Secret Service) instead of a plain file. The keychain entry belongs to <code>--data-dir</code>, so servers with different data directories never share a key. Falls back to the file automatically, with a warning, if the keychain isn&#39;t available, and always on a platform where the keychain library has no persistent store.</td></tr><tr><td><code>--parallel-execution</code></td><td></td><td><code>false</code></td><td>Same as <code>serve</code>&#39;s.</td></tr><tr><td><code>--max-concurrent-nodes &lt;n&gt;</code></td><td></td><td><code>8</code></td><td>Same as <code>serve</code>&#39;s, same clamp-to-1 floor.</td></tr><tr><td><code>--max-workflow-duration-secs &lt;secs&gt;</code></td><td></td><td>none (no limit)</td><td>Same as <code>serve</code>&#39;s: a ceiling combined with the workflow&#39;s own setting via <code>min()</code>, same 10 to 86400 clamp.</td></tr><tr><td><code>--db-pool-size &lt;n&gt;</code></td><td><code>AERINI_DB_POOL_SIZE</code></td><td><code>max(available parallelism, 8)</code></td><td>SQLite connection pool size. Should be at least <code>--max-concurrent-nodes</code> to avoid connection starvation.</td></tr><tr><td><code>--max-concurrent-runs &lt;n&gt;</code></td><td></td><td><code>10</code></td><td>Maximum workflow executions running at once, across every caller.</td></tr><tr><td><code>--max-queue-wait-secs &lt;secs&gt;</code></td><td></td><td><code>30</code></td><td>How long a run request waits for a free execution slot before the server gives up and returns <code>503</code>. <code>0</code> disables the queue entirely, reverting to an immediate <code>503</code> at capacity.</td></tr><tr><td><code>--max-code-memory-mb &lt;mb&gt;</code></td><td></td><td><code>512</code> (Linux only)</td><td>Same as <code>serve</code>&#39;s.</td></tr><tr><td><code>--plugin-dir &lt;dir&gt;</code></td><td></td><td>none</td><td>Same purpose as <code>serve</code>&#39;s. <code>api</code> mode reloads plugins through <code>POST /api/plugins/reload</code> (see <a href="./server-api-reference">Server API Reference</a>) instead of <code>SIGHUP</code>.</td></tr></tbody></table><p>Most flags above are identical between the two subcommands. <code>--file-sandbox-dir</code> is the one that isn&#39;t: <code>serve</code> warns and leaves File nodes unrestricted when it&#39;s absent, <code>api</code> sandboxes to a directory under <code>--data-dir</code> automatically. <code>--port</code>, <code>--token</code>, <code>--data-dir</code>, <code>--allow-origin</code>, <code>--allow-env-vars</code>, <code>--keychain</code>, <code>--db-pool-size</code>, <code>--max-concurrent-runs</code>, and <code>--max-queue-wait-secs</code> exist only on <code>api</code>. <code>--config</code>, <code>--allow-legacy-run-secret</code>, and <code>--i-acknowledge-partial-sandbox</code> exist only on <code>serve</code>.</p><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>Both subcommands log at <code>info</code> by default. Set <code>RUST_LOG</code> to change the level or filter by module (for example <code>RUST_LOG=debug</code>); a value that doesn&#39;t parse falls back to <code>info</code>. Set <code>AERINI_LOG_FORMAT=json</code> to emit one JSON object per log line for a log shipper; any other value keeps the default human-readable format.</p><h2 id="platform-behavior-of-code-sandbox" tabindex="-1">Platform behavior of <code>--code-sandbox</code> <a class="header-anchor" href="#platform-behavior-of-code-sandbox" aria-label="Permalink to &quot;Platform behavior of `--code-sandbox`&quot;">​</a></h2><p><code>--code-sandbox</code> behaves differently on each platform, for both subcommands:</p><ul><li><strong>Linux</strong>: full enforcement. A resolve hook and Node&#39;s permission model block <code>fs</code>/<code>net</code>/<code>child_process</code>-style imports, <code>eval</code>/<code>new Function</code> are separately blocked, and <code>setrlimit</code> caps both CPU time and memory (<code>--max-code-memory-mb</code>, default 512 MB, plus 2 GB of address space for Node.js&#39;s own startup, 4 GB on arm64) on the Node.js subprocess.</li><li><strong>macOS and Windows</strong>: partial. The module import and permission restrictions and the <code>eval</code>/<code>new Function</code> block apply exactly as on Linux, but <code>setrlimit</code> isn&#39;t available, so CPU and memory are uncapped and the per-node timeout is the only real ceiling. <code>serve</code> refuses to start with <code>--allow-code --code-sandbox</code> unless <code>--i-acknowledge-partial-sandbox</code> is also passed; <code>api</code> has no equivalent flag and only prints a warning before continuing. If a host cannot enforce the restrictions at all (for example a Node.js without <code>--permission</code>), the Code node fails with <code>SANDBOX_UNAVAILABLE</code> and the reason instead of running unsandboxed.</li></ul><h2 id="control-commands" tabindex="-1">Control commands <a class="header-anchor" href="#control-commands" aria-label="Permalink to &quot;Control commands&quot;">​</a></h2><p><code>list</code>, <code>stop</code>, <code>start</code>, <code>restart</code>, and <code>status</code> talk to a running <code>api</code>-mode server over HTTP using the same bearer token a client would. They accept no config file and start no server themselves.</p><table tabindex="0"><thead><tr><th>Command</th><th>Positional</th><th>Scope required</th><th>Notes</th></tr></thead><tbody><tr><td><code>list</code></td><td></td><td><code>read</code></td><td>Lists every scheduled workflow.</td></tr><tr><td><code>stop &lt;workflow&gt;</code></td><td>workflow name or ID</td><td><code>read</code> + <code>write</code></td><td><code>read</code> to resolve the name/ID, <code>write</code> to actually stop it. Partial matches are accepted; an ambiguous match prints every candidate instead of guessing.</td></tr><tr><td><code>start &lt;workflow&gt;</code></td><td>workflow name or ID</td><td><code>read</code> + <code>write</code></td><td>Same matching rule as <code>stop</code>. Keeps the workflow&#39;s always-on setting.</td></tr><tr><td><code>restart &lt;workflow&gt;</code></td><td>workflow name or ID</td><td><code>read</code> + <code>write</code></td><td>Calls stop then start against the same REST endpoints a scoped token would use, and keeps the workflow&#39;s always-on setting.</td></tr><tr><td><code>status</code></td><td></td><td><code>read</code></td><td>Identical output to <code>list</code>.</td></tr></tbody></table><p>Each of the five accepts:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Env var</th><th>Default</th></tr></thead><tbody><tr><td><code>--server &lt;url&gt;</code></td><td></td><td><code>http://localhost:7700</code></td></tr><tr><td><code>--token &lt;token&gt;</code></td><td><code>AERINI_TOKEN</code></td><td>required</td></tr></tbody></table><h3 id="tokens" tabindex="-1"><code>tokens</code> <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;`tokens`&quot;">​</a></h3><p>Manages scoped API tokens against a running <code>api</code>-mode server. Every <code>tokens</code> action requires <code>admin</code> scope.</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Args</th><th>Notes</th></tr></thead><tbody><tr><td><code>tokens list</code></td><td><code>--server</code>, <code>--token</code></td><td>Lists active and revoked tokens.</td></tr><tr><td><code>tokens create</code></td><td><code>--label &lt;label&gt;</code> (required), <code>--scopes &lt;list&gt;</code> (default <code>read,write</code>), <code>--expires-in &lt;secs&gt;</code> (optional, omit for a non-expiring token), <code>--server</code>, <code>--token</code></td><td><code>label</code> must be 1 to 256 characters; <code>scopes</code> must be a subset of <code>read</code>, <code>write</code>, <code>admin</code>. Either violation returns an error instead of creating a token. The raw token is only ever printed once, at creation.</td></tr><tr><td><code>tokens revoke &lt;token_id&gt;</code></td><td><code>token_id</code> (positional, from <code>tokens list</code>), <code>--server</code>, <code>--token</code></td><td>Fails with an error if <code>token_id</code> matches the token currently authenticating the call, you can&#39;t revoke your own in-use token.</td></tr></tbody></table><p><code>--server</code> and <code>--token</code> behave the same way here as for <code>list</code>/<code>stop</code>/<code>start</code>/<code>restart</code>/<code>status</code> above.</p><h2 id="restore-key" tabindex="-1"><code>restore-key</code> <a class="header-anchor" href="#restore-key" aria-label="Permalink to &quot;`restore-key`&quot;">​</a></h2><p>Puts a backed-up credential encryption key back into an <code>api</code> data folder. Stop the server first. The key is the value shown by <strong>Backup Encryption Key</strong> in the desktop app, or the contents of a saved <code>aerini.key</code>. It is checked against the saved credentials before anything is written; a key that does not decrypt them changes nothing.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Env var</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--data-dir &lt;dir&gt;</code></td><td><code>AERINI_DATA_DIR</code></td><td><code>~/.aerini-server</code></td><td>Data folder holding <code>credentials.db</code>.</td></tr><tr><td><code>--key-file &lt;path&gt;</code></td><td></td><td>read from standard input</td><td>File holding the key, at most 1 KiB. A key typed at a terminal is refused, since it would stay on screen; pipe it in or use a file.</td></tr><tr><td><code>--keychain</code></td><td></td><td>off</td><td>Restore into the OS keychain, as <code>api --keychain</code> stores it, and remove <code>aerini.key</code>.</td></tr></tbody></table><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="./server-deploy">Server Deployment</a>, for getting either mode actually running</li><li><a href="./server-api-reference">Server API Reference</a>, for the REST routes these flags and control commands sit on top of</li><li><a href="./../guide/security">Security</a>, for the reasoning behind the sandboxing, SSRF, and token defaults</li><li><a href="./../guide/credentials">Credentials</a>, for how <code>serve</code>&#39;s environment-variable credentials and <code>api</code>&#39;s own encrypted store differ</li></ul>',29)])])}const u=t(r,[["render",c]]);export{f as __pageData,u as default};
